use anyhow::{Result, anyhow};

use std::fs;
use std::path::Path;
use std::process::Command;

use crate::{command_exists, rust};

const IOS_TARGETS: [&str; 2] = ["aarch64-apple-ios", "aarch64-apple-ios-sim"];

const IOS_SIM_TARGET: &str = "aarch64-apple-ios-sim";
const IOS_DEVICE_TARGET: &str = "aarch64-apple-ios";

// Everything in here is regenerated by `xcodegen` and the bindings generator.
const IOS_GITIGNORE: &str = r#"build/
Generated/
*.xcodeproj
.DS_Store
"#;

pub fn install_ios_toolchain() {
    Command::new("rustup")
        .args(["target", "add"])
        .args(IOS_TARGETS)
        .status()
        .expect("failed to run rustup");
}

pub fn check_ios() {
    println!("[iOS]");
    if command_exists("xcodebuild") {
        println!("\x1b[32m[✓]\x1b[0m xcode is installed");
    } else {
        println!("\x1b[31m[✗]\x1b[0m xcode is not installed");
    };
    if command_exists("xcodegen") {
        println!("\x1b[32m[✓]\x1b[0m xcodegen is installed");
    } else {
        println!("\x1b[31m[✗]\x1b[0m xcodegen is not installed");
    };
    if command_exists("xcrun") {
        println!("\x1b[32m[✓]\x1b[0m xcrun is installed");
    } else {
        println!("\x1b[31m[✗]\x1b[0m xcrun is not installed");
    };
    for target in IOS_TARGETS {
        println!(
            "{} target {target}",
            if rust::target_installed(target) {
                "\x1b[32m[✓]\x1b[0m"
            } else {
                "\x1b[31m[✗]\x1b[0m"
            }
        );
    }
}

pub fn create_ios(name: &str) {
    let ios_dir = format!("./{name}/ios");
    fs::create_dir_all(format!("{ios_dir}/Sources")).expect("failed to create iOS sources dir");
    fs::create_dir_all(format!("{ios_dir}/Generated")).expect("failed to create generated dir");

    let app = app_name(name);
    let lib_name = lib_name(name);

    fs::write(
        format!("{ios_dir}/project.yml"),
        project_yml(&app, &lib_name, name),
    )
    .expect("failed to write project.yml");

    fs::write(format!("{ios_dir}/Sources/{app}App.swift"), app_swift(&app))
        .expect("failed to write app swift file");

    fs::write(
        format!("{ios_dir}/Sources/ContentView.swift"),
        content_view_swift(),
    )
    .expect("failed to write ContentView.swift");

    fs::write(format!("{ios_dir}/.gitignore"), IOS_GITIGNORE)
        .expect("failed to write iOS .gitignore");

    Command::new("xcodegen")
        .args(["generate"])
        .current_dir(&ios_dir)
        .status()
        .expect("failed to run xcodegen");
}

/// Swift module / library name used by cargo and UniFFI.
fn lib_name(name: &str) -> String {
    name.replace('-', "_")
}

/// Turn an arbitrary project name into a valid Swift/Xcode identifier, e.g. `my-app` -> `MyApp`.
fn app_name(name: &str) -> String {
    let mut app = String::new();
    for part in name.split(|c: char| !c.is_alphanumeric()) {
        let mut chars = part.chars();
        if let Some(first) = chars.next() {
            app.extend(first.to_uppercase());
            app.push_str(chars.as_str());
        }
    }

    if app.is_empty() {
        app.push_str("App");
    } else if app.chars().next().is_some_and(|c| c.is_ascii_digit()) {
        app.insert_str(0, "App");
    }

    app
}

/// Bundle identifiers may contain alphanumerics, hyphens and periods, but no underscores.
fn bundle_id(name: &str) -> String {
    let sanitized: String = name
        .to_lowercase()
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '-' || c == '.' {
                c
            } else {
                '-'
            }
        })
        .collect();

    format!("com.example.{sanitized}")
}

fn project_yml(app: &str, lib_name: &str, name: &str) -> String {
    format!(
        r#"name: {app}
options:
  bundleIdPrefix: com.example
  deploymentTarget:
    iOS: "16.0"
  createIntermediateGroups: true

settings:
  base:
    SWIFT_VERSION: "5.9"
    RUST_TARGET: {IOS_SIM_TARGET}
    GENERATE_INFOPLIST_FILE: YES
    CODE_SIGNING_ALLOWED: NO
    INFOPLIST_KEY_UILaunchScreen_Generation: YES
    INFOPLIST_KEY_UIApplicationSceneManifest_Generation: YES

targets:
  {app}:
    type: application
    platform: iOS
    sources:
      - path: Sources
      - path: Generated
        includes:
          - "*.swift"
    settings:
      base:
        PRODUCT_BUNDLE_IDENTIFIER: {bundle_id}
        PRODUCT_NAME: {app}
        SWIFT_INCLUDE_PATHS:
          - $(SRCROOT)/Generated
        LIBRARY_SEARCH_PATHS:
          - $(SRCROOT)/../rust/target/$(RUST_TARGET)/$(CONFIGURATION:lower)
        OTHER_LDFLAGS:
          - -l{lib_name}
"#,
        bundle_id = bundle_id(name),
    )
}

fn app_swift(app: &str) -> String {
    format!(
        r#"import SwiftUI

@main
struct {app}App: App {{
    var body: some Scene {{
        WindowGroup {{
            ContentView()
        }}
    }}
}}
"#
    )
}

fn content_view_swift() -> String {
    r#"import SwiftUI

struct ContentView: View {
    var body: some View {
        Text(getGreeting())
            .font(.title.bold())
            .padding()
    }
}
"#
    .to_string()
}

pub fn list_ios_devices() {
    println!("Available iOS Simulators:\n");
    Command::new("xcrun")
        .args(["simctl", "list", "devices", "available"])
        .status()
        .expect("failed to list iOS simulators");
}

pub fn launch_ios_emulator(name: &str) {
    println!("Launching iOS Simulator...\n");

    match resolve_simulator(name) {
        Ok(udid) => {
            // Ignore failures here: the simulator may already be booted.
            let _ = Command::new("xcrun")
                .args(["simctl", "boot", &udid])
                .output();
            open_simulator_app();
        }
        Err(e) => println!("{e}"),
    }
}

fn open_simulator_app() {
    let developer_dir = Command::new("xcode-select")
        .arg("-p")
        .output()
        .ok()
        .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_string())
        .unwrap_or_else(|| "/Applications/Xcode.app/Contents/Developer".to_string());

    let candidates = [
        format!("{developer_dir}/Applications/Simulator.app"),
        format!("{developer_dir}/../Applications/Simulator.app"),
        format!("{developer_dir}/Applications/DeviceHub.app"),
    ];

    for candidate in candidates {
        if Path::new(&candidate).exists() {
            let _ = Command::new("open").arg(candidate).status();
            return;
        }
    }
}

fn resolve_simulator(preferred: &str) -> Result<String> {
    let output = Command::new("xcrun")
        .args(["simctl", "list", "devices", "available"])
        .output()
        .map_err(|e| anyhow!("failed to list iOS simulators: {e}"))?;

    let listing = String::from_utf8_lossy(&output.stdout);
    parse_simulator_udid(&listing, preferred).ok_or_else(|| {
        if preferred.is_empty() {
            anyhow!("No available iOS simulator found")
        } else {
            anyhow!("No available iOS simulator found matching '{preferred}'")
        }
    })
}

/// Find a simulator UDID from `xcrun simctl list devices available` output.
/// Prefers a booted simulator, falling back to the first available one.
fn parse_simulator_udid(listing: &str, preferred: &str) -> Option<String> {
    let mut first = None;

    for line in listing.lines() {
        let line = line.trim();
        let Some((name, rest)) = line.split_once(" (") else {
            continue;
        };
        let Some(udid) = find_udid(rest) else {
            continue;
        };

        if !preferred.is_empty() {
            if name == preferred || udid == preferred {
                return Some(udid.to_string());
            }
        } else if line.contains("(Booted)") {
            return Some(udid.to_string());
        } else if first.is_none() {
            first = Some(udid.to_string());
        }
    }

    first
}

/// Find a UDID-shaped token in the parenthesized parts of a simulator listing line, e.g.
/// `5268B420-2975-4800-821D-4B2A2C19846D) (Booted)`.
fn find_udid(rest: &str) -> Option<&str> {
    let mut remaining = rest;

    loop {
        let end = remaining.find(')')?;
        let token = &remaining[..end];

        if token.len() == 36 && token.contains('-') {
            return Some(token);
        }

        let after = &remaining[end + 1..];
        let start = after.find('(')?;
        remaining = &after[start + 1..];
    }
}

fn generate_swift_bindings() -> Result<()> {
    println!("\nGenerating Swift UniFFI bindings...");

    let lib_name = rust::get_lib_name()?;
    let args = bindgen_args(&lib_name);

    println!("Running command: cargo {}", args.join(" "));

    let status = Command::new("cargo")
        .args(args)
        .current_dir("./rust")
        .status()
        .expect("failed to generate UniFFI Swift bindings");

    if !status.success() {
        return Err(anyhow!("UniFFI Swift bindings generation failed"));
    }

    Ok(())
}

fn bindgen_args(lib_name: &str) -> Vec<String> {
    vec![
        "run".to_string(),
        "-p".to_string(),
        "uniffi-bindgen-swift".to_string(),
        "--".to_string(),
        "--swift-sources".to_string(),
        "--headers".to_string(),
        "--modulemap".to_string(),
        "--module-name".to_string(),
        format!("{lib_name}FFI"),
        "--modulemap-filename".to_string(),
        "module.modulemap".to_string(),
        format!("src:{lib_name}"),
        "../ios/Generated".to_string(),
    ]
}

pub fn generate_ios_bindings() -> Result<()> {
    generate_swift_bindings()
}

fn get_project_name() -> Result<String> {
    let content = fs::read_to_string("./ios/project.yml")?;
    parse_project_name(&content)
        .ok_or_else(|| anyhow!("Could not find project name in project.yml"))
}

fn parse_project_name(project_yml: &str) -> Option<String> {
    project_yml.lines().find_map(|line| {
        line.trim()
            .strip_prefix("name:")
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(str::to_string)
    })
}

fn get_bundle_id() -> Result<String> {
    let content = fs::read_to_string("./ios/project.yml")?;
    parse_bundle_id(&content)
        .ok_or_else(|| anyhow!("Could not find PRODUCT_BUNDLE_IDENTIFIER in project.yml"))
}

fn parse_bundle_id(project_yml: &str) -> Option<String> {
    project_yml.lines().find_map(|line| {
        line.trim()
            .strip_prefix("PRODUCT_BUNDLE_IDENTIFIER:")
            .map(str::trim)
            .filter(|id| !id.is_empty())
            .map(str::to_string)
    })
}

/// Build the Rust library and app for the iOS simulator, then install and launch it.
pub fn build_ios_debug(device: &str) -> Result<()> {
    println!("\nBuilding iOS...");

    let project = get_project_name()?;
    let bundle_id = get_bundle_id()?;
    let simulator = resolve_simulator(device)?;

    println!("\nBuilding rust lib...");
    let status = Command::new("cargo")
        .args([
            "build",
            "--manifest-path",
            "./rust/Cargo.toml",
            "--target",
            IOS_SIM_TARGET,
            "--features",
            "ios",
        ])
        .status()
        .expect("failed to build rust lib");

    if !status.success() {
        return Err(anyhow!("Rust build failed"));
    }

    generate_swift_bindings()?;

    println!("\nGenerating Xcode project...");
    let status = Command::new("xcodegen")
        .arg("generate")
        .current_dir("./ios")
        .status()
        .expect("failed to run xcodegen");

    if !status.success() {
        return Err(anyhow!("xcodegen failed"));
    }

    println!("\nBuilding iOS app...");
    let status = Command::new("xcodebuild")
        .args([
            "-project",
            &format!("{project}.xcodeproj"),
            "-scheme",
            &project,
            "-sdk",
            "iphonesimulator",
            "-destination",
            &format!("platform=iOS Simulator,id={simulator}"),
            "-derivedDataPath",
            "build",
            "build",
        ])
        .current_dir("./ios")
        .status()
        .expect("failed to build iOS app");

    if !status.success() {
        return Err(anyhow!("xcodebuild failed"));
    }

    // Ignore failures here: the simulator may already be booted.
    let _ = Command::new("xcrun")
        .args(["simctl", "boot", &simulator])
        .output();
    open_simulator_app();

    let app_path = format!("./ios/build/Build/Products/Debug-iphonesimulator/{project}.app");
    let status = Command::new("xcrun")
        .args(["simctl", "install", &simulator, &app_path])
        .status()
        .expect("failed to install iOS app");

    if !status.success() {
        return Err(anyhow!("failed to install iOS app"));
    }

    Command::new("xcrun")
        .args(["simctl", "launch", &simulator, &bundle_id])
        .status()
        .expect("failed to launch iOS app");

    println!("\niOS build done.");

    Ok(())
}

/// Build a release app for physical devices. The resulting app is unsigned.
pub fn build_ios_release() -> Result<()> {
    println!("\nBuilding iOS release...");

    let project = get_project_name()?;

    println!("\nBuilding rust lib...");
    let status = Command::new("cargo")
        .args([
            "build",
            "--manifest-path",
            "./rust/Cargo.toml",
            "--target",
            IOS_DEVICE_TARGET,
            "--features",
            "ios",
            "--release",
        ])
        .status()
        .expect("failed to build rust lib");

    if !status.success() {
        return Err(anyhow!("Rust build failed"));
    }

    generate_swift_bindings()?;

    println!("\nGenerating Xcode project...");
    let status = Command::new("xcodegen")
        .arg("generate")
        .current_dir("./ios")
        .status()
        .expect("failed to run xcodegen");

    if !status.success() {
        return Err(anyhow!("xcodegen failed"));
    }

    println!("\nBuilding iOS app...");
    let status = Command::new("xcodebuild")
        .args([
            "-project",
            &format!("{project}.xcodeproj"),
            "-scheme",
            &project,
            "-sdk",
            "iphoneos",
            "-configuration",
            "Release",
            "-destination",
            "generic/platform=iOS",
            "-derivedDataPath",
            "build",
            &format!("RUST_TARGET={IOS_DEVICE_TARGET}"),
            "build",
        ])
        .current_dir("./ios")
        .status()
        .expect("failed to build iOS app");

    if !status.success() {
        return Err(anyhow!("xcodebuild failed"));
    }

    println!("\niOS release build done.");

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_app_name() {
        assert_eq!(app_name("demo"), "Demo");
        assert_eq!(app_name("my-app"), "MyApp");
        assert_eq!(app_name("my_app"), "MyApp");
        assert_eq!(app_name("123app"), "App123app");
        assert_eq!(app_name("---"), "App");
    }

    #[test]
    fn test_bundle_id() {
        assert_eq!(bundle_id("demo"), "com.example.demo");
        assert_eq!(bundle_id("my-app"), "com.example.my-app");
        assert_eq!(bundle_id("my_app"), "com.example.my-app");
        assert_eq!(bundle_id("MyApp"), "com.example.myapp");
    }

    #[test]
    fn test_project_yml() {
        let yml = project_yml("Demo", "demo", "demo");
        assert!(yml.contains("name: Demo"));
        assert!(yml.contains("PRODUCT_BUNDLE_IDENTIFIER: com.example.demo"));
        assert!(yml.contains("RUST_TARGET: aarch64-apple-ios-sim"));
        assert!(yml.contains("$(SRCROOT)/../rust/target/$(RUST_TARGET)/$(CONFIGURATION:lower)"));
        assert!(yml.contains("- -ldemo"));
        assert!(yml.contains("path: Generated"));
        assert!(yml.contains("$(SRCROOT)/Generated"));
    }

    #[test]
    fn test_ios_gitignore() {
        assert!(IOS_GITIGNORE.contains("build/"));
        assert!(IOS_GITIGNORE.contains("Generated/"));
        assert!(IOS_GITIGNORE.contains("*.xcodeproj"));
    }

    #[test]
    fn test_app_swift() {
        let swift = app_swift("Demo");
        assert!(swift.contains("@main"));
        assert!(swift.contains("struct DemoApp: App"));
        assert!(swift.contains("ContentView()"));
    }

    #[test]
    fn test_content_view_calls_rust() {
        assert!(content_view_swift().contains("Text(getGreeting())"));
    }

    #[test]
    fn test_parse_project_name() {
        let yml = project_yml("Demo", "demo", "demo");
        assert_eq!(parse_project_name(&yml).unwrap(), "Demo");
        assert!(parse_project_name("options:\n  bundleIdPrefix: com.example\n").is_none());
    }

    #[test]
    fn test_parse_bundle_id() {
        let yml = project_yml("Demo", "demo", "demo");
        assert_eq!(parse_bundle_id(&yml).unwrap(), "com.example.demo");
        assert!(parse_bundle_id("options:\n  bundleIdPrefix: com.example\n").is_none());
    }

    #[test]
    fn test_bindgen_args() {
        let args = bindgen_args("my_app");
        assert_eq!(
            args,
            vec![
                "run",
                "-p",
                "uniffi-bindgen-swift",
                "--",
                "--swift-sources",
                "--headers",
                "--modulemap",
                "--module-name",
                "my_appFFI",
                "--modulemap-filename",
                "module.modulemap",
                "src:my_app",
                "../ios/Generated",
            ]
        );
    }

    const SIMULATOR_LISTING: &str = r#"
== Devices ==
-- iOS 18.3 --
    iPhone 16 Pro (5268B420-2975-4800-821D-4B2A2C19846D) (Shutdown)
    iPhone 16 (EC1AB375-83C3-4763-95FC-A48C0827B315) (Booted)
-- iOS 18.5 --
    iPad Pro 11-inch (M4) (00D863C7-98BB-4B4A-AC65-C6FFE209F0D9) (Shutdown)
"#;

    #[test]
    fn test_parse_simulator_udid_prefers_booted() {
        assert_eq!(
            parse_simulator_udid(SIMULATOR_LISTING, "").unwrap(),
            "EC1AB375-83C3-4763-95FC-A48C0827B315"
        );
    }

    #[test]
    fn test_parse_simulator_udid_falls_back_to_first() {
        let listing = SIMULATOR_LISTING.replace("(Booted)", "(Shutdown)");
        assert_eq!(
            parse_simulator_udid(&listing, "").unwrap(),
            "5268B420-2975-4800-821D-4B2A2C19846D"
        );
    }

    #[test]
    fn test_parse_simulator_udid_by_name_and_udid() {
        assert_eq!(
            parse_simulator_udid(SIMULATOR_LISTING, "iPhone 16 Pro").unwrap(),
            "5268B420-2975-4800-821D-4B2A2C19846D"
        );
        assert_eq!(
            parse_simulator_udid(SIMULATOR_LISTING, "00D863C7-98BB-4B4A-AC65-C6FFE209F0D9")
                .unwrap(),
            "00D863C7-98BB-4B4A-AC65-C6FFE209F0D9"
        );
    }

    #[test]
    fn test_parse_simulator_udid_missing() {
        assert!(parse_simulator_udid(SIMULATOR_LISTING, "Pixel").is_none());
        assert!(parse_simulator_udid("", "").is_none());
    }
}
